create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','worker');
create type public.order_status as enum ('Baru','Menunggu konfirmasi','Dikonfirmasi','Pekerja ditugaskan','Dalam pengerjaan','Selesai','Dibatalkan','Perlu tindak lanjut');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, name text not null, phone text unique not null, role public.app_role not null default 'worker', active boolean not null default true, created_at timestamptz not null default now());
create table public.workers(user_id uuid primary key references public.profiles(id) on delete cascade, area text not null default 'Ciamis', available boolean not null default true, verified boolean not null default false);
create table public.service_packages(id uuid primary key default gen_random_uuid(), name text unique not null, price integer not null check(price>=0), duration_hours integer not null, scope text not null, active boolean not null default true, updated_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(), code text unique not null default upper(substr(encode(gen_random_bytes(8),'hex'),1,10)), customer_name text not null, phone text not null, address text not null, package_id uuid references public.service_packages(id), package_name text not null, price integer not null check(price>=0), visit_date date not null, visit_time text not null, notes text not null default '', status public.order_status not null default 'Baru', payment_status text not null default 'Belum dibayar' check(payment_status in ('Belum dibayar','DP','Lunas','Refund')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_assignments(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, worker_id uuid not null references public.profiles(id), wage integer not null default 0 check(wage>=0), checklist_before jsonb not null default '[]', checklist_after jsonb not null default '[]', assigned_at timestamptz not null default now(), unique(order_id,worker_id));
create table public.order_expenses(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,kind text not null,amount integer not null check(amount>=0),note text not null default '',created_at timestamptz not null default now());
create table public.worker_applications(id uuid primary key default gen_random_uuid(),name text not null,phone text not null,area text not null,experience text not null default '',status text not null default 'Menunggu',created_at timestamptz not null default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id),name text not null,rating integer not null check(rating between 1 and 5),comment text not null,created_at timestamptz not null default now());
create or replace function public.has_role(required public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role=required and active); $$;
alter table public.profiles enable row level security; alter table public.workers enable row level security; alter table public.service_packages enable row level security; alter table public.orders enable row level security; alter table public.order_assignments enable row level security; alter table public.order_expenses enable row level security; alter table public.worker_applications enable row level security; alter table public.reviews enable row level security;
create policy "profiles self or admin read" on public.profiles for select to authenticated using(id=auth.uid() or public.has_role('admin'));
create policy "admin profile management" on public.profiles for all to authenticated using(public.has_role('admin')) with check(public.has_role('admin'));
create policy "workers self or admin" on public.workers for select to authenticated using(user_id=auth.uid() or public.has_role('admin'));
create policy "admin worker management" on public.workers for all to authenticated using(public.has_role('admin')) with check(public.has_role('admin'));
create policy "packages public read" on public.service_packages for select using(active or public.has_role('admin'));
create policy "admin package management" on public.service_packages for all to authenticated using(public.has_role('admin')) with check(public.has_role('admin'));
create policy "order insert public" on public.orders for insert to anon,authenticated with check(status='Baru' and payment_status='Belum dibayar');
create policy "admin all orders" on public.orders for all to authenticated using(public.has_role('admin')) with check(public.has_role('admin'));
create policy "worker assigned order read" on public.orders for select to authenticated using(exists(select 1 from public.order_assignments a where a.order_id=id and a.worker_id=auth.uid()));
create policy "assignment admin full" on public.order_assignments for all to authenticated using(public.has_role('admin')) with check(public.has_role('admin'));
create policy "worker assigned read" on public.order_assignments for select to authenticated using(worker_id=auth.uid());
create policy "worker checklist update" on public.order_assignments for update to authenticated using(worker_id=auth.uid()) with check(worker_id=auth.uid());
create policy "expense admin only" on public.order_expenses for all to authenticated using(public.has_role('admin')) with check(public.has_role('admin'));
create policy "application public submit" on public.worker_applications for insert to anon,authenticated with check(status='Menunggu');
create policy "application admin manage" on public.worker_applications for all to authenticated using(public.has_role('admin')) with check(public.has_role('admin'));
create policy "reviews public read" on public.reviews for select using(true);
create policy "reviews public submit" on public.reviews for insert to anon,authenticated with check(rating between 1 and 5);
insert into public.service_packages(name,price,duration_hours,scope) values ('Setrika',100000,4,'Setrika, lipat, rapikan pakaian yang sudah dicuci dan kering'),('Cuci + Setrika',150000,6,'Cuci sesuai fasilitas rumah, jemur/keringkan, setrika pakaian kering'),('All-in Bersih & Beres',220000,6,'Sapu, pel, debu permukaan, merapikan ruang, bersih ringan dapur/kamar mandi') on conflict(name) do nothing;
